/** Reuse complete independent frozen answers; no extra search or horizon escalation. */
import {readFile,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';
const paths=['research/competitive-engine-v1/js-compulsory-q-ablation.json','research/competitive-engine-v1/js-broad-mate-five.json','research/competitive-engine-v1/js-random-tactics.json'];const inputs=await Promise.all(paths.map(async path=>({path,bytes:await readFile(path)})));const [ablation,broad,random]=inputs.map(x=>JSON.parse(x.bytes));const rows=[];
for(const change of ablation.actionChanges){const position=ablation.cases.find(c=>c.id===change.id).position;const source=[...broad.cases,...random.cases].find(c=>JSON.stringify(c.position)===JSON.stringify(position));assert(source?.complete);const answer=action=>{const a=source.answers.find(x=>JSON.stringify(x.action)===JSON.stringify(action));assert(a);return a.mateWithin5;};rows.push({id:change.id,position,candidate:change.candidate,baseline:change.base,candidateMate5:answer(change.candidate.action),baselineMate5:answer(change.base.action),independentSource:source});}
const out={purpose:'Classify all six changed depth4 decisions with already complete independent frozen mate5 answers at identical positions,20000nodes200ms original caps. No new queries or cap/horizon increase. Short mate membership does not prove a winning save, improved strength, or baseline missed win; Black13baselinebishop5 previously proved mate7. Two candidate-only mate5, one both, three neither. No actionable winning-save proof; keep temporary policy unadopted and stop this family rather than optimize mate delay.',hashes:Object.fromEntries(inputs.map(x=>[x.path,createHash('sha256').update(x.bytes).digest('hex')])),script:await readFile(new URL(import.meta.url),'utf8'),rows};await writeFile('research/competitive-engine-v1/js-compulsory-q-classification.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({cases:rows.length,candidateOnly:rows.filter(x=>x.candidateMate5&&!x.baselineMate5).length,both:rows.filter(x=>x.candidateMate5&&x.baselineMate5).length,neither:rows.filter(x=>!x.candidateMate5&&!x.baselineMate5).length,newSearchQueries:0}));
